"""The capture the grader reads (T2.5). No Docker: the REST client is a stand-in.

`capture` is the only function in the grading path that touches the network, which is exactly
why it is worth pinning. A namespace missing from it would not raise — it would make every
check about that namespace quietly true, and `guards` blind to whatever happened there.
"""

from __future__ import annotations

from typing import Any

from fixtures import stage2_records as make
from stage2 import state as state_mod


class FakeRest:
    """Answers the two calls `capture` is allowed to make, and records what it was asked."""

    def __init__(self) -> None:
        self.asked: list[str] = []
        self.tree = {
            "people": [make.person("I0000", "Rosalind", "Steinbrecht")],
            "families": [make.family("F0000", father="I0000")],
            "sources": [make.source("S0000", "Der Grippewinter")],
            "notes": [make.note("N0000", "text")],
            "tags": [make.tag("Unbestätigt")],
        }

    def object_counts(self) -> dict[str, int]:
        return {name: len(records) for name, records in self.tree.items()}

    def objects(self, namespace: str) -> list[dict[str, Any]]:
        self.asked.append(namespace)
        return self.tree[namespace]


def test_capture_reads_every_namespace_a_check_can_ask_about() -> None:
    rest = FakeRest()

    captured = state_mod.capture(rest)

    assert rest.asked == list(state_mod.NAMESPACES)
    assert captured.counts["tags"] == 1
    assert captured.by_id("people")["I0000"]["gramps_id"] == "I0000"


def test_the_snapshot_view_is_the_shape_movement_already_diffs() -> None:
    captured = state_mod.capture(FakeRest())

    assert captured.snapshot["objects"]["people"] == [("I0000", "h-I0000")]
    assert captured.snapshot["total"] == 5


def test_a_family_is_selectable_by_its_members_not_by_their_slot() -> None:
    """The slot assignment is the product's own rule and several use cases test it — a view
    that encoded it would be asserting the answer instead of asking the question."""
    tree = state_mod.capture(FakeRest()).tree

    assert tree.families[0]["members"] == frozenset({"I0000"})
    assert tree.people[0]["surname"] == "Steinbrecht"


def test_the_person_signature_ignores_family_membership() -> None:
    tags: dict[str, str] = {}
    person = make.person("I0000", "Rosalind", "Steinbrecht", families=("h-F0000",))
    unmarried = {**person, "family_list": []}

    assert state_mod.person_signature(person, tags) == state_mod.person_signature(unmarried, tags)


def test_the_person_signature_sees_a_tag_by_name() -> None:
    tags = {"h-tag-Unbestätigt": "Unbestätigt"}
    plain = make.person("I0000", "Rosalind", "Steinbrecht")
    marked = make.person("I0000", "Rosalind", "Steinbrecht", tags=("Unbestätigt",))

    assert state_mod.person_signature(plain, tags) != state_mod.person_signature(marked, tags)
